def write(p,s):
 if p.endswith('.html'):
  # Protect the person's name, while leaving the prose available to translators.
  parts=re.split(r'(<[^>]+>)',s);skip=False
  for i,part in enumerate(parts):
   if part.startswith('<'):
    if re.match(r'<(?:script|style|title)\b',part):skip=True
    elif re.match(r'</(?:script|style|title)>',part):skip=False
   elif not skip:
    parts[i]=part.replace('Mark Serdyuk','<span class="notranslate" translate="no" lang="en">Mark Serdyuk</span>')
  s=''.join(parts)
 p=ROOT/p;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s,encoding='utf-8')
