def orbit_position(i):
 a=i*math.tau/len(CASES)+.65
 rx=math.sin(a)*.337*1.24;ry=math.cos(a)*.337*.49
 return (50+100*(rx*math.cos(-.25)-ry*math.sin(-.25)),50+100*(rx*math.sin(-.25)+ry*math.cos(-.25)))
def orbit_fallback():
 # Inline geometry remains visible if Canvas or the animation script is unavailable.
 points=json.loads((ROOT/'assets/data/land.json').read_text())
 dots=[]
 for lon,lat in points:
  a=math.radians(lon)+.65;lat=math.radians(lat)
  x=math.sin(a)*math.cos(lat);y=-math.sin(lat);z=math.cos(a)*math.cos(lat)
  if z<0:continue
  px=250+(x*math.cos(-.16)-y*math.sin(-.16))*168.5
  py=250+(x*math.sin(-.16)+y*math.cos(-.16))*168.5
  dots.append(f'M{px:.1f},{py:.1f}h1.6v1.6h-1.6z')
 return '<svg class="orbit-fallback" viewBox="0 0 500 500" aria-hidden="true"><circle cx="250" cy="250" r="168.5" fill="var(--bg)" stroke="currentColor" opacity=".5"/><g fill="none" stroke="currentColor" opacity=".18"><circle cx="250" cy="250" r="212"/><ellipse cx="250" cy="250" rx="84" ry="168.5"/><ellipse cx="250" cy="250" rx="168.5" ry="65"/><path d="M81.5 250h337M250 81.5v337"/></g><path fill="currentColor" opacity=".75" d="'+''.join(dots)+'"/></svg><script type="application/json" id="orbit-land">'+json.dumps(points,separators=(',',':'))+'</script>'
